package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * A station key ("outstation1:" and base64url JSON {relay, channel, key}, as the outstation and a friend's invite
 * give it; "portal1:" from before the name was outstation): where the plugin sends the game, and with what key.
 */
public final class Attach
{
	/** The Outside relay's host: the only one the Plugin Hub's version talks to (11/16/2026, the reviewer on
	 *  runelite/plugin-hub#20811: "Hub plugins aren't allowed to take a URL from a server response then connect to it…
	 *  make sure the hostname portion of relay is relay.ghillie.workers.dev"). */
	public static final String HOME_HOST = "relay.ghillie.workers.dev";
	/** Its address, the base of every request the Hub's version makes. */
	public static final String HOME = "https://" + HOME_HOST;

	private final String relay;
	private final String channel;
	private final String key;

	public Attach(String relay, String channel, String key)
	{
		this.relay = relay;
		this.channel = channel;
		this.key = key;
	}

	public String getRelay()
	{
		return relay;
	}

	public String getChannel()
	{
		return channel;
	}

	public String getKey()
	{
		return key;
	}

	/** The key read (with RuneLite's own Gson), or null when it isn't one. */
	public static Attach parse(String code, Gson gson)
	{
		if (code == null)
		{
			return null;
		}
		String c = code.trim();
		int colon = c.indexOf(':');
		if (colon < 0)
		{
			return null;
		}
		String prefix = c.substring(0, colon);
		if (!prefix.equals("outstation1") && !prefix.equals("portal1"))
		{
			return null;
		}
		try
		{
			String json = new String(Base64.getUrlDecoder().decode(c.substring(colon + 1)), StandardCharsets.UTF_8);
			JsonObject o = gson.fromJson(json, JsonObject.class);
			String relay = o.get("relay").getAsString();
			String channel = o.get("channel").getAsString();
			String key = o.get("key").getAsString();
			if (relay.isEmpty() || channel.isEmpty() || key.length() < 8)
			{
				return null;
			}
			// (the Hub's version: a key for any other relay is no key, whether pasted or from /claim's answer, and
			// every request is built on HOME, never on what the key says; the whole plugin, in developer mode, also
			// takes an outstation's own relay or a local one)
			if (!isHome(relay))
			{
				return null;
			}
			return new Attach(HOME, channel, key);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Whether a key's relay is the Outside relay itself: relay.ghillie.workers.dev, as https://, wss:// or bare, with no
	 *  port, path or anything else. */
	public static boolean isHome(String relay)
	{
		if (relay == null)
		{
			return false;
		}
		String r = relay.trim().replaceAll("/+$", "");
		if (r.startsWith("https://"))
		{
			r = r.substring(8);
		}
		else if (r.startsWith("wss://"))
		{
			r = r.substring(6);
		}
		return r.equalsIgnoreCase(HOME_HOST);
	}

	/** The snapshot's address (11/16/2026; docs/protocol.md, "The snapshot"): POST http(s)://…/game/<channel>?key=…&v=…. */
	public String postUrl(String version)
	{
		// (&proof=1, 11/17/2026: the answer says what the page's proof did, while it's still to be made)
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/game/" + enc(channel) + "?") + "&v=" + enc(version) + "&proof=1";
	}

	/** The relay's keep for the page (11/14/2026): http(s)://…/keep/<channel>/<what>?key=… (a bare relay as https://). */
	public String keepUrl(String what)
	{
		String base = relay.trim().replaceAll("/+$", "");
		if (base.startsWith("wss://"))
		{
			base = "https://" + base.substring(6);
		}
		else if (base.startsWith("ws://"))
		{
			base = "http://" + base.substring(5);
		}
		else if (!base.contains("://"))
		{
			base = "https://" + base;
		}
		return base + "/keep/" + enc(channel) + "/" + enc(what) + "?key=" + enc(key);
	}

	/** The page's address for the Dink plugin's webhooks (11/16/2026, "Copy my Dink address"): http(s)://…/dink/<channel>?key=…,
	 *  on the relay every request goes to. Only copied for the player to paste into Dink; never fetched here. */
	public String dinkAddress()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/dink/" + enc(channel) + "?");
	}

	/** Who stands behind the page (11/15/2026): http(s)://…/proof/<channel>, anyone's. */
	public String proofUrl()
	{
		return keepUrl("x").replaceFirst("/keep/.*$", "/proof/" + enc(channel));
	}

	/** Friends only, set from the plugin (11/16/2026, the permissions review): http(s)://…/code/<channel>?key=…. */
	public String codeUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/code/" + enc(channel) + "?");
	}

	/** The page taken down by its own key (11/16/2026): http(s)://…/channels/<channel>?key=…. */
	public String takeDownUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/channels/" + enc(channel) + "?");
	}

	/** A token to tend the page's chat from the page, handed in by its own key (11/16/2026): http(s)://…/tend/<channel>?key=…. */
	public String tendUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/tend/" + enc(channel) + "?");
	}

	/** The page, opened to tend its chat: the token in the fragment, which no server sees (11/16/2026). */
	public String tendPage(String token)
	{
		return page() + "#tend=" + token;
	}

	/** The page's kept game, as anyone reads it (403 when it's friends only and no code is given). */
	public String gameReadUrl()
	{
		return keepUrl("x").replaceFirst("/keep/.*$", "/game/" + enc(channel));
	}

	/** The page with a watch code, for friends (11/16/2026). */
	public String page(String code)
	{
		return code == null || code.isEmpty() ? page() : page() + "?code=" + enc(code);
	}

	/** The outstation's page on Outside. */
	public String page()
	{
		// (11/16/2026: outside.wiki/<name>, as Open my page opens it; it was ghillie.wiki/outside?player=)
		return "https://outside.wiki/" + enc(channel);
	}

	private static String enc(String s)
	{
		return URLEncoder.encode(s, StandardCharsets.UTF_8).replace("+", "%20");
	}
}

package wiki.outside;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Kill counts and clue counts as the game's chat says them (11/16/2026, Jace: field reports for Hub players without
 * Dink): "Your Vorkath kill count is: 418", "You have completed 152 hard Treasure Trails." Kept per account on this
 * RuneLite's profile and sent with each update (OutsidePlugin.read, "kc"); the relay reports a count that's gone up.
 * The patterns are Dink's (github.com/pajlads/DinkPlugin: KillCountNotifier, ClueNotifier; BSD 2-Clause, Copyright (c)
 * 2022, pajlads), as the whole plugin's Reports reads them. Kept apart from RuneLite so it's tested.
 */
final class Counts
{
	private static final Pattern KILL = Pattern.compile("^Your (?:completed )?(.+?) (?:(?:kill|chest|completion|harvest|success) )?count is: ?([\\d,]+)\\b.*$");
	private static final Pattern CLUE = Pattern.compile("^You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?\\s*$",
		Pattern.CASE_INSENSITIVE);
	/** at most this many bosses kept (the game has fewer) */
	static final int MOST = 250;
	/** the most a count can say */
	static final int TOP = 10_000_000;
	/** never kept or sent: a Wilderness boss's count says where they've been (the relay's WILDERNESS_BOSSES, the same) */
	private static final String[] WILDERNESS = {"artio", "callisto", "calvar'ion", "chaos elemental", "chaos fanatic",
		"crazy archaeologist", "scorpia", "spindel", "venenatis", "vet'ion", "king black dragon", "revenant"};

	private final Map<String, Integer> kills = new TreeMap<>();
	private final Map<String, Integer> clues = new TreeMap<>();

	/** A game message read: true when it changed a count. */
	synchronized boolean take(String line)
	{
		if (line == null)
		{
			return false;
		}
		String m = line.trim();
		Matcher k = KILL.matcher(m);
		if (k.matches())
		{
			String boss = k.group(1).trim();
			return !wilderness(boss) && put(kills, boss, number(k.group(2)));
		}
		Matcher c = CLUE.matcher(m);
		if (c.matches())
		{
			return put(clues, c.group(2).toLowerCase(Locale.ROOT), number(c.group(1)));
		}
		return false;
	}

	static boolean wilderness(String boss)
	{
		String b = boss.toLowerCase(Locale.ROOT);
		for (String w : WILDERNESS)
		{
			if (b.startsWith(w))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean put(Map<String, Integer> to, String name, int n)
	{
		if (name.isEmpty() || name.length() > 60 || n < 0 || n > TOP || (!to.containsKey(name) && to.size() >= MOST))
		{
			return false;
		}
		Integer was = to.put(name, n);
		return was == null || was != n;
	}

	private static int number(String s)
	{
		try
		{
			return Integer.parseInt(s.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** {"kills": {boss: n}, "clues": {tier: n}}, or null with none. */
	synchronized JsonObject json()
	{
		if (kills.isEmpty() && clues.isEmpty())
		{
			return null;
		}
		JsonObject o = new JsonObject(), k = new JsonObject(), c = new JsonObject();
		kills.forEach(k::addProperty);
		clues.forEach(c::addProperty);
		o.add("kills", k);
		o.add("clues", c);
		return o;
	}

	/** The counts as kept (json()'s shape); anything else leaves them empty. */
	synchronized void load(JsonObject o)
	{
		kills.clear();
		clues.clear();
		if (o == null)
		{
			return;
		}
		for (String part : new String[]{"kills", "clues"})
		{
			if (!o.has(part) || !o.get(part).isJsonObject())
			{
				continue;
			}
			for (Map.Entry<String, JsonElement> e : o.getAsJsonObject(part).entrySet())
			{
				try
				{
					if (!part.equals("kills") || !wilderness(e.getKey()))
					{
						put(part.equals("kills") ? kills : clues, e.getKey(), e.getValue().getAsInt());
					}
				}
				catch (RuntimeException ignored)
				{
				}
			}
		}
	}
}

package wiki.outside;

import com.google.gson.JsonObject;

/**
 * The goal item (11/17/2026, update 3; Goji Berries: "what if you could set a goal item from the plugin then it shows
 * your kc and dryness on the top of ur profile"): the item a player is after, picked from the game's own item search
 * (the side tab's "Set my goal item", or ::outsidegoal), sent to their page's keep as {"id", "name", "model"}; when the
 * game's collection log line names it, {"got": {"at", "counts"}} with it, the kill and clue counts then (the page reads
 * the kill count it took from those). The page works out how dry they are from the wiki's drop rates.
 */
final class Goal
{
	private Goal()
	{
	}

	/** The RuneScape profile's own settings: the item, and when it was got (0: not yet), with the counts then. */
	static final String ITEM = "goalItem";
	static final String GOT = "goalGot";
	static final String GOT_COUNTS = "goalGotCounts";

	/** Whether the game's "New item added to your collection log" line is the goal's. */
	static boolean isIt(String added, String goalName)
	{
		return added != null && goalName != null && !goalName.isEmpty()
			&& added.trim().equalsIgnoreCase(goalName.trim());
	}

	/** What goes to the keep: the item, its model (null: none to send), and when it was got (0: not yet). */
	static JsonObject body(int id, String name, JsonObject model, long gotAt, JsonObject countsThen)
	{
		JsonObject o = new JsonObject();
		o.addProperty("id", id);
		o.addProperty("name", name == null ? "" : name.replaceAll("[\\x00-\\x1f\\x7f]", " ").trim());
		if (model != null)
		{
			o.add("model", model);
		}
		if (gotAt > 0)
		{
			JsonObject got = new JsonObject();
			got.addProperty("at", gotAt);
			if (countsThen != null)
			{
				got.add("counts", countsThen);
			}
			o.add("got", got);
		}
		return o;
	}
}

package wiki.outside;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the plugin reads for the player's page beyond what's worn and carried, kept apart from RuneLite so it's tested
 * (docs/protocol.md, "Kept for the page"):
 * <ul>
 * <li>an item's charges, from the game's own chat line;</li>
 * <li>the bank, as the relay keeps it;</li>
 * <li>the deathbank (the Item Retrieval Service's), as the relay keeps it;</li>
 * <li>the character's model, as the page draws it;</li>
 * </ul>
 */
public final class Kept
{
	private Kept()
	{
	}

	// ---- charges (Jace: "show charges on the items that have charges like my tonalztics of ralos and archivist's
	// folio, if you can collect that info from the client"): the game says them only in its chat, when an item's
	// checked ("Your tonalztics of ralos has 1,234 charges left.") or as it's used, so they're read from there, as the
	// Hub's charge plugins read them

	/** "1,234 charges", "1 charge", "has 50 charges left", "(57 charges)", "uses remaining: 12" … */
	private static final Pattern CHARGES = Pattern.compile(
		"(?i)(?:\\b([0-9][0-9,]*)\\s+(?:charges?|uses?|scrolls?|doses?)\\b)|(?:(?:charges?|uses?)(?:\\s+(?:left|remaining))?\\s*[:]?\\s+([0-9][0-9,]*)\\b)");
	/** "none", "no charges left", "has run out" */
	private static final Pattern NONE = Pattern.compile("(?i)\\b(no charges|no more charges|has run out of charges|has no charges|is out of charges)\\b");

	/** The charges a game message tells of, or null: none told. 0 for "no charges". */
	public static Integer charges(String message)
	{
		if (message == null)
		{
			return null;
		}
		if (NONE.matcher(message).find())
		{
			return 0;
		}
		Matcher m = CHARGES.matcher(message);
		if (!m.find())
		{
			return null;
		}
		String n = (m.group(1) != null ? m.group(1) : m.group(2)).replace(",", "");
		try
		{
			long v = Long.parseLong(n);
			return v > Integer.MAX_VALUE ? null : (int) v;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** An item's name as the game says it in chat: lower case, without its "(charged)", "(e)", "(4)" or the like. */
	public static String spoken(String name)
	{
		return name == null ? "" : name.replaceAll("\\s*\\([^)]*\\)\\s*$", "").trim().toLowerCase(Locale.ROOT);
	}

	/** Whether a message is about this item (its spoken name in it), its name at least 5 letters so a short word ("ring") never does. */
	public static boolean about(String message, String name)
	{
		String n = spoken(name);
		return n.length() >= 5 && message != null && message.toLowerCase(Locale.ROOT).contains(n);
	}

	// ---- the bank (Jace: "an option for people to capture their entire bank, just as the liveloadout twitch
	// extension/plugin offers"): every slot in the bank's own order, a placeholder as [its item, 0], the tabs' counts
	// (the game's BANK_TAB_1 to 9; the main tab is what's left), and each item's name and price

	/** {"items", "tabs", "names"} as the relay keeps it. */
	public static JsonObject bank(int[] ids, int[] quantities, int[] tabs, Map<Integer, Object[]> names)
	{
		JsonObject o = new JsonObject();
		JsonArray items = new JsonArray();
		for (int i = 0; i < ids.length && i < quantities.length; i++)
		{
			if (ids[i] > 0 && quantities[i] >= 0)
			{
				items.add(Kit.pair(ids[i], quantities[i]));
			}
		}
		o.add("items", items);
		JsonArray t = new JsonArray();
		for (int n : tabs)
		{
			t.add(Math.max(0, n));
		}
		o.add("tabs", t);
		JsonObject nm = new JsonObject();
		for (Map.Entry<Integer, Object[]> e : names.entrySet())
		{
			JsonArray np = new JsonArray();
			np.add((String) e.getValue()[0]);
			np.add(Math.max(0, ((Number) e.getValue()[1]).longValue()));
			nm.add(String.valueOf(e.getKey()), np);
		}
		o.add("names", nm);
		return o;
	}

	// ---- the deathbank (11/16/2026, Jace: "show an open Deathbank like the Hespori deathbank on someone's profile"):
	// what the game's Item Retrieval Service holds for them after a death in an instance (Hespori, Zulrah, Vorkath...),
	// read when they look in it (its window fills the game's GRAVESTONE inventory while the gravestone's own window
	// isn't open), and which one it is by the varp IF1 the window sets, a locked and an unlocked value each (locked: its
	// fee unpaid). The values are Dude, Where's My Stuff's (github.com/Thource/dude-wheres-my-stuff, its DeathbankType;
	// BSD 2-Clause, Copyright 2022 Thource), the ones it marks confirmed and the rest as it has them.

	/** Each deathbank: its name, its locked and its unlocked IF1 values, the place the game's line names it by ("You have
	 *  items stored in an item retrieval service...", spaces taken out; null, none known) and the regions it's made
	 *  from a death in (RuneLite's Discord plugin's, as Presence has them; none for the quests'). */
	static final Object[][] DEATHBANKS = {
		{"Volcanic Mine", 1, 2, "FossilIsland", new int[]{15263, 15262}},
		{"Grotesque Guardians", 3, 4, null, new int[]{6727}},
		{"Vorkath", 5, 6, "Rellekka", new int[]{9023}},
		{"Dragon Slayer II", 7, 8, null, new int[]{}},
		{"A Taste of Hope", 9, 10, null, new int[]{}},
		{"Theatre of Blood", 11, 12, "TheatreofBlood", new int[]{12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379}},
		{"Alchemical Hydra", 13, 14, "KaruulmSlayerDungeon", new int[]{5536}},
		{"Hespori", 15, 16, "FarmingGuild", new int[]{5021}},
		{"The Mimic", 17, 18, null, new int[]{}},
		{"Song of the Elves", 19, 20, "elvenrebel", new int[]{}},
		{"Song of the Elves", 21, 22, "elvenrebel", new int[]{}},
		{"The Fremennik Exiles", 23, 24, null, new int[]{}},
		{"The Nightmare", 25, 26, "Shura", new int[]{15515}},
		{"Phosani's Nightmare", 27, 28, "SisterSenga", new int[]{}},
		{"Hallowed Sepulchre", 29, 30, null, new int[]{8797, 9051, 9052, 9053, 9054, 9309, 9563, 9565, 9821, 10074, 10075, 10077}},
		{"Sins of the Father", 31, 32, null, new int[]{}},
		{"Zulrah", 33, 0, "Zul-Andra", new int[]{9007}},
		{"Nex", 36, 37, null, new int[]{11601}},
	};

	/** The game's line after a death that made a deathbank (the start of it). */
	public static final String DEATHBANK_LINE = "You have items stored in an item retrieval service";

	/** Which deathbank a death made: by the place the game's line names, else by the region they died in, else "Unknown". */
	public static String deathbankAt(String line, int region)
	{
		String flat = line == null ? "" : line.replace(" ", "");
		for (Object[] d : DEATHBANKS)
		{
			if (d[3] != null && flat.contains((String) d[3]))
			{
				return (String) d[0];
			}
		}
		for (Object[] d : DEATHBANKS)
		{
			for (int r : (int[]) d[4])
			{
				if (r == region)
				{
					return (String) d[0];
				}
			}
		}
		return "Unknown";
	}

	/** What a death took (11/16/2026, Jace: "make it fill in the moment they die too"): what they carried and wore as they
	 *  fell, less what they still have once they're back (the items kept on death), as {ids, how many}, in the order
	 *  they were carried. */
	public static int[][] lost(int[] beforeIds, int[] beforeQs, int[] afterIds, int[] afterQs)
	{
		Map<Integer, Long> left = new java.util.LinkedHashMap<>();
		for (int i = 0; i < beforeIds.length && i < beforeQs.length; i++)
		{
			if (beforeIds[i] > 0 && beforeQs[i] > 0)
			{
				left.merge(beforeIds[i], (long) beforeQs[i], Long::sum);
			}
		}
		for (int i = 0; i < afterIds.length && i < afterQs.length; i++)
		{
			if (afterIds[i] > 0 && afterQs[i] > 0 && left.containsKey(afterIds[i]))
			{
				left.merge(afterIds[i], (long) -afterQs[i], Long::sum);
			}
		}
		left.values().removeIf(n -> n <= 0);
		int[][] out = new int[2][left.size()];
		int k = 0;
		for (Map.Entry<Integer, Long> e : left.entrySet())
		{
			out[0][k] = e.getKey();
			out[1][k++] = (int) Math.min(Integer.MAX_VALUE, e.getValue());
		}
		return out;
	}

	/** {where, locked} for the IF1 value the retrieval window set, {"Unknown", false} for one not on the list, or null
	 *  (-1) when no deathbank's window is open. */
	public static Object[] deathbankWhere(int if1)
	{
		if (if1 < 0)
		{
			return null;
		}
		for (Object[] d : DEATHBANKS)
		{
			if ((int) d[1] == if1)
			{
				return new Object[]{d[0], true};
			}
			if ((int) d[2] == if1)
			{
				return new Object[]{d[0], false};
			}
		}
		return new Object[]{"Unknown", false};
	}

	/** {"where", "locked", "items", "names"} as the relay keeps it, or null when it's empty (taken off the page); "from":
	 *  "death" when it's worked out at the death (lost), not read from its window. */
	public static JsonObject deathbank(String where, boolean locked, int[] ids, int[] quantities, Map<Integer, Object[]> names)
	{
		return deathbank(where, locked, ids, quantities, names, false);
	}

	public static JsonObject deathbank(String where, boolean locked, int[] ids, int[] quantities, Map<Integer, Object[]> names, boolean atDeath)
	{
		JsonArray items = new JsonArray();
		for (int i = 0; i < ids.length && i < quantities.length; i++)
		{
			if (ids[i] > 0 && quantities[i] > 0)
			{
				items.add(Kit.pair(ids[i], quantities[i]));
			}
		}
		if (items.size() == 0)
		{
			return null;
		}
		JsonObject o = new JsonObject();
		o.addProperty("where", where);
		o.addProperty("locked", locked);
		o.add("items", items);
		JsonObject nm = new JsonObject();
		for (Map.Entry<Integer, Object[]> e : names.entrySet())
		{
			JsonArray np = new JsonArray();
			np.add((String) e.getValue()[0]);
			np.add(Math.max(0, ((Number) e.getValue()[1]).longValue()));
			nm.add(String.valueOf(e.getKey()), np);
		}
		o.add("names", nm);
		if (atDeath)
		{
			o.addProperty("from", "death");
		}
		return o;
	}

	// ---- the model (Jace: "upload a captured model of their character onto their profile page just as RuneProfile
	// does; but we can make ours look cooler and rendered to our liking/in our own style"): only its shape and its
	// colours, as RuneProfile's exporter reads them (its ModelMeshBuilder, BSD 2-Clause: plugin/README.md, "Credits"),
	// the faces the game never draws left out

	/** A face the game never draws (its third colour), and a face shaded flat (one colour, not one a corner). */
	static final int HIDDEN = -2, FLAT = -1;

	/**
	 * The model as the page draws it: every face drawn but the hidden and the wholly see-through ones.
	 * <ul>
	 * <li>"v": vertices (x, y, z, the game's units, rounded); "f": faces (three vertices' places each)</li>
	 * <li>"c": each face's colour unlit (the game's packed HSL, or -1 for a textured face), as since 11/14/2026</li>
	 * <li>(11/15/2026, Jace: "draw ours as accurately to the game as possible, shading and geometry") "g": each face's
	 * three corners as the game has lit them (its packed HSL each; a flat face's one colour three times; a textured
	 * face's three 7-bit lightnesses, which multiply its texture)</li>
	 * <li>"a": each face's opacity, 0 to 255 (only when any face is see-through); "p": each face's draw priority (only when
	 * the model has them)</li>
	 * <li>"t": each face's texture id, -1 for none, and "uv": its three corners' texture coordinates, u then v, times
	 * 4096 (0s for an untextured face), found as the client finds them from the face's texture triangle (RuneProfile's
	 * ModelMeshBuilder.computeFaceUvs, BSD 2-Clause): only when any face is textured</li>
	 * </ul>
	 * Null arrays are taken as none.
	 */
	public static JsonObject model(float[] x, float[] y, float[] z, int vertices, int[] a, int[] b, int[] c, int faces,
		int[] colors1, int[] colors3, short[] unlit, byte[] transparencies, short[] textures)
	{
		return model(x, y, z, vertices, a, b, c, faces, colors1, null, colors3, unlit, transparencies, textures, null, null, null, null, null);
	}

	public static JsonObject model(float[] x, float[] y, float[] z, int vertices, int[] a, int[] b, int[] c, int faces,
		int[] colors1, int[] colors2, int[] colors3, short[] unlit, byte[] transparencies, short[] textures,
		byte[] priorities, byte[] textureFaces, int[] tex1, int[] tex2, int[] tex3)
	{
		JsonObject o = new JsonObject();
		JsonArray v = new JsonArray();
		for (int i = 0; i < vertices; i++)
		{
			v.add(clamp(Math.round(x[i])));
			v.add(clamp(Math.round(y[i])));
			v.add(clamp(Math.round(z[i])));
		}
		JsonArray f = new JsonArray(), col = new JsonArray(), lit = new JsonArray(), alpha = new JsonArray();
		JsonArray pri = new JsonArray(), tex = new JsonArray(), uv = new JsonArray();
		boolean seeThrough = false, anyTexture = false;
		for (int i = 0; i < faces; i++)
		{
			if (colors3 != null && colors3[i] == HIDDEN)
			{
				continue;
			}
			int al = transparencies == null ? 255 : 255 - (transparencies[i] & 0xff);
			if (al == 0)
			{
				continue;
			}
			if (a[i] < 0 || b[i] < 0 || c[i] < 0 || a[i] >= vertices || b[i] >= vertices || c[i] >= vertices)
			{
				continue;
			}
			f.add(a[i]);
			f.add(b[i]);
			f.add(c[i]);
			int tid = textures != null ? textures[i] : -1;
			boolean textured = tid != -1;
			int hsl = unlit != null ? unlit[i] & 0xffff : (colors1 != null ? colors1[i] & 0xffff : 0);
			col.add(textured ? -1 : hsl);
			if (colors1 != null)
			{
				boolean flat = colors3 == null || colors3[i] == FLAT;
				int c1 = colors1[i];
				int c2 = flat || colors2 == null ? c1 : colors2[i];
				int c3 = flat ? c1 : colors3[i];
				lit.add(textured ? c1 : c1 & 0xffff);
				lit.add(textured ? c2 : c2 & 0xffff);
				lit.add(textured ? c3 : c3 & 0xffff);
			}
			alpha.add(al);
			seeThrough |= al != 255;
			pri.add(priorities == null ? 0 : priorities[i] & 0xff);
			tex.add(tid);
			if (textured && textureFaces != null && tex1 != null && (textureFaces[i] & 0xff) < tex1.length)
			{
				anyTexture = true;
				float[] u = new float[3], w = new float[3];
				uvs(x, y, z, a[i], b[i], c[i], tex1[textureFaces[i] & 0xff], tex2[textureFaces[i] & 0xff], tex3[textureFaces[i] & 0xff], u, w);
				for (int k = 0; k < 3; k++)
				{
					uv.add(fin(u[k]));
					uv.add(fin(w[k]));
				}
			}
			else
			{
				for (int k = 0; k < 6; k++)
				{
					uv.add(0);
				}
			}
		}
		o.add("v", v);
		o.add("f", f);
		o.add("c", col);
		if (colors1 != null)
		{
			o.add("g", lit);
		}
		if (seeThrough)
		{
			o.add("a", alpha);
		}
		if (priorities != null)
		{
			o.add("p", pri);
		}
		if (anyTexture)
		{
			o.add("t", tex);
			o.add("uv", uv);
		}
		return o;
	}

	/** One frame of a motion: every vertex's x, y, z rounded (as "v"'s), as little-endian 16-bit numbers, in base64. */
	public static String frame(float[] x, float[] y, float[] z, int vertices)
	{
		java.nio.ByteBuffer b = java.nio.ByteBuffer.allocate(vertices * 6).order(java.nio.ByteOrder.LITTLE_ENDIAN);
		for (int i = 0; i < vertices; i++)
		{
			b.putShort((short) clamp(Math.round(x[i])));
			b.putShort((short) clamp(Math.round(y[i])));
			b.putShort((short) clamp(Math.round(z[i])));
		}
		return java.util.Base64.getEncoder().encodeToString(b.array());
	}

	/** A motion's frames: {"fps", "v": [each frame (frame)]}. */
	public static JsonObject frames(java.util.List<String> frames, double fps)
	{
		JsonObject o = new JsonObject();
		o.addProperty("fps", Math.round(fps * 100) / 100.0);
		JsonArray v = new JsonArray();
		for (String f : frames)
		{
			v.add(f);
		}
		o.add("v", v);
		return o;
	}

	// ---- effects and the ground (11/15/2026, Jace: "can you build the effects (spot animations) and the ground into the
	// model viewer/capturer?")

	/**
	 * How many of a player model's vertices are the player's own: the client may hand out the player's model with their
	 * effects (spot animations) merged in after them. When the last {@code fx} vertices lie exactly where the effects'
	 * own models put them across (x and z the same, in order), the player's own are the ones before; otherwise all.
	 * {@code fxX}/{@code fxZ}: each effect's vertices' x and z, in order.
	 */
	public static int ownVertices(float[] x, float[] z, int vertices, java.util.List<float[]> fxX, java.util.List<float[]> fxZ, int[] fxCounts)
	{
		int s = 0;
		for (int n : fxCounts)
		{
			s += n;
		}
		if (s <= 0 || s >= vertices)
		{
			return vertices;
		}
		int at = vertices - s;
		for (int k = 0; k < fxCounts.length; k++)
		{
			float[] ex = fxX.get(k), ez = fxZ.get(k);
			for (int i = 0; i < fxCounts[k]; i++, at++)
			{
				if (Math.abs(x[at] - ex[i]) > 0.5f || Math.abs(z[at] - ez[i]) > 0.5f)
				{
					return vertices;
				}
			}
		}
		return vertices - s;
	}

	/** A model (as {@link #model}) cut to its first {@code keep} vertices: every face reaching past them dropped, with
	 *  its colours, opacity, priority and texture. */
	public static JsonObject trim(JsonObject m, int keep)
	{
		JsonArray v = m.getAsJsonArray("v");
		if (v == null || v.size() <= keep * 3)
		{
			return m;
		}
		JsonArray f = m.getAsJsonArray("f");
		int nf = f.size() / 3;
		JsonObject o = new JsonObject();
		JsonArray nv = new JsonArray();
		for (int i = 0; i < keep * 3; i++)
		{
			nv.add(v.get(i));
		}
		o.add("v", nv);
		String[] per = {"c", "a", "p", "t"};
		JsonArray of = new JsonArray(), og = new JsonArray(), ouv = new JsonArray();
		JsonArray[] op = new JsonArray[per.length];
		for (int k = 0; k < per.length; k++)
		{
			op[k] = m.has(per[k]) ? new JsonArray() : null;
		}
		for (int t = 0; t < nf; t++)
		{
			int a = f.get(t * 3).getAsInt(), b = f.get(t * 3 + 1).getAsInt(), c = f.get(t * 3 + 2).getAsInt();
			if (a >= keep || b >= keep || c >= keep)
			{
				continue;
			}
			of.add(a);
			of.add(b);
			of.add(c);
			for (int k = 0; k < per.length; k++)
			{
				if (op[k] != null)
				{
					op[k].add(m.getAsJsonArray(per[k]).get(t));
				}
			}
			if (m.has("g"))
			{
				for (int q = 0; q < 3; q++)
				{
					og.add(m.getAsJsonArray("g").get(t * 3 + q));
				}
			}
			if (m.has("uv"))
			{
				for (int q = 0; q < 6; q++)
				{
					ouv.add(m.getAsJsonArray("uv").get(t * 6 + q));
				}
			}
		}
		o.add("f", of);
		for (int k = 0; k < per.length; k++)
		{
			if (op[k] != null)
			{
				o.add(per[k], op[k]);
			}
		}
		if (m.has("g"))
		{
			o.add("g", og);
		}
		if (m.has("uv"))
		{
			o.add("uv", ouv);
		}
		return o;
	}

	/** A colour the game marks "don't draw" on a tile. */
	static final int TILE_HIDDEN = 12345678;

	/**
	 * The ground round the player as a model (the same shape as {@link #model}, three vertices a face), from its triangles:
	 * each {@code tri} is x, y, z for its three corners (already in the player's model space), then its three colours
	 * (the game's packed HSL, lit), then its texture (-1 for none), then u, v for each corner times 4096. A face with a
	 * colour the game never draws is left out.
	 */
	public static JsonObject ground(java.util.List<int[]> tris)
	{
		JsonObject o = new JsonObject();
		JsonArray v = new JsonArray(), f = new JsonArray(), c = new JsonArray(), g = new JsonArray(), t = new JsonArray(), uv = new JsonArray();
		boolean anyTexture = false;
		int n = 0;
		for (int[] q : tris)
		{
			if (q[9] == TILE_HIDDEN || q[10] == TILE_HIDDEN || q[11] == TILE_HIDDEN)
			{
				continue;
			}
			for (int k = 0; k < 9; k++)
			{
				v.add(clamp(q[k]));
			}
			f.add(n);
			f.add(n + 1);
			f.add(n + 2);
			n += 3;
			boolean textured = q[12] >= 0;
			anyTexture |= textured;
			c.add(textured ? -1 : q[9] & 0xffff);
			for (int k = 0; k < 3; k++)
			{
				// (a textured face's corners as a model's: 7-bit lightnesses that multiply its texture)
				g.add(textured ? q[9 + k] & 127 : q[9 + k] & 0xffff);
			}
			t.add(q[12]);
			for (int k = 0; k < 6; k++)
			{
				uv.add(textured ? q[13 + k] : 0);
			}
		}
		o.add("v", v);
		o.add("f", f);
		o.add("c", c);
		o.add("g", g);
		if (anyTexture)
		{
			o.add("t", t);
			o.add("uv", uv);
		}
		return o;
	}

	/** A texture coordinate times 4096, kept to what the relay takes. */
	private static int fin(float t)
	{
		if (Float.isNaN(t) || Float.isInfinite(t))
		{
			return 0;
		}
		return (int) Math.max(-1_000_000, Math.min(1_000_000, Math.round(t * 4096f)));
	}

	/** A face's corners' texture coordinates from its texture triangle (origin, then its two axes), as the client finds them. */
	static void uvs(float[] vx, float[] vy, float[] vz, int fa, int fb, int fc, int ta, int tb, int tc, float[] u, float[] v)
	{
		float ox = vx[ta], oy = vy[ta], oz = vz[ta];
		float ux = vx[tb] - ox, uy = vy[tb] - oy, uz = vz[tb] - oz;
		float wx = vx[tc] - ox, wy = vy[tc] - oy, wz = vz[tc] - oz;
		float[][] p = {{vx[fa] - ox, vy[fa] - oy, vz[fa] - oz}, {vx[fb] - ox, vy[fb] - oy, vz[fb] - oz}, {vx[fc] - ox, vy[fc] - oy, vz[fc] - oz}};
		float nx = uy * wz - uz * wy, ny = uz * wx - ux * wz, nz = ux * wy - uy * wx;
		float px = wy * nz - wz * ny, py = wz * nx - wx * nz, pz = wx * ny - wy * nx;
		float s = 1f / (px * ux + py * uy + pz * uz);
		for (int k = 0; k < 3; k++)
		{
			u[k] = (px * p[k][0] + py * p[k][1] + pz * p[k][2]) * s;
		}
		px = uy * nz - uz * ny; py = uz * nx - ux * nz; pz = ux * ny - uy * nx;
		s = 1f / (px * wx + py * wy + pz * wz);
		for (int k = 0; k < 3; k++)
		{
			v[k] = (px * p[k][0] + py * p[k][1] + pz * p[k][2]) * s;
		}
	}

	private static int clamp(int n)
	{
		return Math.max(-8192, Math.min(8192, n));
	}

}

package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * What the plugin knows of the game, field by field (the relay's names: docs/protocol.md, "The game"), and what's
 * changed since it was last sent: only those fields go, each whole. Kept apart from RuneLite so it can be tested.
 */
public class Kit
{
	/** the fields as last sent */
	private final Map<String, JsonElement> sent = new LinkedHashMap<>();
	/** the item ids whose name and price have gone already */
	private final Set<Integer> named = new TreeSet<>();

	/**
	 * The writer for the relay (the game socket's, the snapshot's; 11/16/2026, Jace: his goblin task never reached his page): RuneLite's Gson, which
	 * plugins are given, leaves out an object's null members as it writes, so a field's null that clears it (a part
	 * switched off, the slayer task's "area": null) had been going as nothing, or as a field the relay refuses. The same
	 * Gson, with nulls kept; RuneLite's own otherwise untouched.
	 */
	static Gson wire(Gson runelite)
	{
		return runelite.newBuilder().serializeNulls().create();
	}

	/** Everything goes again (a new connection, or logging in). */
	public void forget()
	{
		sent.clear();
		named.clear();
	}

	/** The fields of `now` that differ from what was last sent (and, once taken, count as sent). */
	public JsonObject changes(Map<String, JsonElement> now)
	{
		JsonObject out = new JsonObject();
		for (Map.Entry<String, JsonElement> e : now.entrySet())
		{
			JsonElement last = sent.get(e.getKey());
			if (last == null || !last.equals(e.getValue()))
			{
				out.add(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/** What `changes` gave is now sent. */
	public void took(JsonObject changes)
	{
		for (Map.Entry<String, JsonElement> e : changes.entrySet())
		{
			if (!e.getKey().equals("items"))
			{
				sent.put(e.getKey(), e.getValue());
			}
		}
	}

	/** Ids not named yet, from the item fields (worn, inv, bag, pouch, seeds, barrel, quiver), marked as named. */
	public Set<Integer> unnamed(Map<String, JsonElement> now)
	{
		Set<Integer> ids = ids(now);
		ids.removeAll(named);
		named.addAll(ids);
		return ids;
	}

	/** Every item id in the item fields (worn, inv, bag, pouch, seeds, barrel, quiver): a snapshot names them all
	 *  (11/16/2026). */
	public static Set<Integer> ids(Map<String, JsonElement> now)
	{
		Set<Integer> ids = new TreeSet<>();
		for (String f : new String[]{"worn", "inv", "bag", "pouch", "seeds", "barrel"})
		{
			JsonElement a = now.get(f);
			if (a != null && a.isJsonArray())
			{
				for (JsonElement slot : a.getAsJsonArray())
				{
					if (slot != null && slot.isJsonArray() && slot.getAsJsonArray().size() > 0)
					{
						ids.add(slot.getAsJsonArray().get(0).getAsInt());
					}
				}
			}
		}
		JsonElement q = now.get("quiver");
		if (q != null && q.isJsonArray() && q.getAsJsonArray().size() > 0)
		{
			ids.add(q.getAsJsonArray().get(0).getAsInt());
		}
		return ids;
	}

	/** A container's slots as [id, quantity] or null for an empty one, `size` of them (or as many as there are). */
	public static JsonArray slots(int[] ids, int[] quantities, int size)
	{
		JsonArray a = new JsonArray();
		int n = size > 0 ? size : ids.length;
		for (int i = 0; i < n; i++)
		{
			int id = i < ids.length ? ids[i] : -1;
			int q = i < quantities.length ? quantities[i] : 0;
			if (id <= 0 || q <= 0)
			{
				a.add(JsonNull.INSTANCE);
			}
			else
			{
				a.add(pair(id, q));
			}
		}
		return a;
	}

	/** A container's items only (no empty slots): the looting bag, the rune pouch. */
	public static JsonArray items(int[] ids, int[] quantities)
	{
		JsonArray a = new JsonArray();
		for (int i = 0; i < ids.length && i < quantities.length; i++)
		{
			if (ids[i] > 0 && quantities[i] > 0)
			{
				a.add(pair(ids[i], quantities[i]));
			}
		}
		return a;
	}

	/**
	 * Held back somewhere dangerous: "paused", and what was worn and carried emptied with it, so the relay keeps
	 * nothing of what they took in (it keeps the last of each field otherwise), nor the vitals and prayers.
	 */
	/** Everything taken off the page (11/16/2026, the permissions review): sent as "Send to my Outside page" goes off, so
	 *  the page doesn't go on showing what was last sent. */
	public static JsonObject cleared()
	{
		JsonObject o = held("x");
		o.remove("paused");
		o.addProperty("off", true);
		o.add("skills", new JsonObject());
		o.add("charges", new JsonObject());
		o.add("quests", JsonNull.INSTANCE);
		o.add("diaries", JsonNull.INSTANCE);
		o.add("combat", JsonNull.INSTANCE);
		o.add("slayer", JsonNull.INSTANCE);
		o.add("delve", JsonNull.INSTANCE);
		o.add("presence", JsonNull.INSTANCE);   // (what they're doing as Discord shows it, 11/16/2026)
		return o;
	}

	public static JsonObject held(String why)
	{
		JsonObject o = new JsonObject();
		o.addProperty("paused", why);
		o.add("worn", new JsonArray());
		o.add("inv", new JsonArray());
		o.add("bag", new JsonArray());
		o.add("pouch", new JsonArray());
		o.add("seeds", new JsonArray());
		o.add("barrel", new JsonArray());
		o.add("quiver", JsonNull.INSTANCE);
		o.add("vitals", new JsonObject());
		o.add("prayers", new JsonArray());
		o.add("anim", JsonNull.INSTANCE);   // (the live view's animation, 11/15/2026)
		return o;
	}

	public static JsonArray pair(long a, long b)
	{
		JsonArray p = new JsonArray();
		p.add(a);
		p.add(b);
		return p;
	}
}

package wiki.outside;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(OutsideConfig.GROUP)
public interface OutsideConfig extends Config
{
	String GROUP = "outside";

	// (11/17/2026, Jace: "organize our plugin settings menu so it's less confusing. use runeprofile as your example":
	// the switches under a few headings, each with a short name; what each does in its description, under the hand)
	@ConfigSection(name = "Your page", description = "Whether this plugin sends to your Outside page at all", position = 0)
	String pageSection = "page";

	@ConfigSection(name = "On your page", description = "What goes on your page, each its own switch", position = 1)
	String shownSection = "shown";

	@ConfigSection(name = "What you're doing", description = "What your page and Outside.wiki's globe say you're doing", position = 2)
	String doingSection = "doing";

	@ConfigSection(name = "Advanced", description = "Your page's key, if you were given one", position = 9, closedByDefault = true)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "stationKey",
		name = "Station key",
		description = "Your page's key (it starts outstation1:): made for you by \"Make my Outside page\" in the Outside"
			+ " side tab and kept with your account, so this stays blank. Paste one here only if you were given one.",
		secret = true,
		position = 0,
		section = advancedSection
	)
	default String stationKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "send",
		name = "Send to my Outside page",
		description = "What's switched on below goes to the Outside relay (on Cloudflare) when you press Update my page in the"
			+ " Outside side tab, and hourly while you're logged in; what you're doing goes as it changes. Your Outside page"
