	/**
	 * Where the player is, an instance's as its template lies on the map (11/09/2026: instances are allowed, placed
	 * where they're opened), as RuneLite's own Discord plugin reads it; outside one, where they are; on a boat, where the
	 * boat is at sea (onMainWorld, 11/10/2026). Null before there's a player, or for a moment while a boat's being set up.
	 */
	private WorldPoint here()
	{
		return here(client, client.getLocalPlayer());
	}

	static WorldPoint here(Client client, Player me)
	{
		LocalPoint at = me == null ? null : onMainWorld(client.getTopLevelWorldView(), me.getLocalLocation());
		return at == null ? null : WorldPoint.fromLocalInstance(client, at);
	}

	/**
	 * A point on the main world (11/10/2026, Jace: "I notice there are no players on their boats at sea"). With Sailing,
	 * a player on a boat stands in the boat's own world view (a WorldEntity's), and their local point is the deck's, so
	 * read as it was it gave the boat's own template, off the map, and nothing went. Here the deck's point is carried
	 * out to where the boat is on the main world, the way RuneLite's own code does it (runelite/runelite at e7098b7,
	 * Perspective.localToMinimap: the top-level view's worldEntities().byIndex(the point's world view), then
	 * transformToMainWorld) and the Sailing plugin's SailingUtil.getTopLevelLocalPoint (LlemonDuck/sailing at af987f3);
	 * Group Ironmen Tracker and Shortest Path take the boat's own place (worldEntity.getLocalLocation()), here the fallback.
	 * Null for a point in a world view with no boat on the main world (as while a world hop sets it up): never the deck's.
	 */
	static LocalPoint onMainWorld(WorldView top, LocalPoint p)
	{
		if (p == null || p.getWorldView() == WorldView.TOPLEVEL)
		{
			return p;
		}
		IndexedObjectSet<? extends WorldEntity> boats = top == null ? null : top.worldEntities();
		WorldEntity boat = boats == null ? null : boats.byIndex(p.getWorldView());
		if (boat == null)
		{
			return null;
		}
		LocalPoint at = boat.transformToMainWorld(p);
		if (at == null)
		{
			at = boat.getLocalLocation();
		}
		return at == null ? null : new LocalPoint(at.getX(), at.getY(), WorldView.TOPLEVEL);
	}

	/**
	 * Ferox Enclave (11/10/2026, Jace: "it is a safe area/haven in the wilderness"): the town inside its barriers, where
	 * no player can attack another, as Shortest Path's WildernessChecker draws it (github.com/Skretzo/shortest-path,
	 * src/main/java/shortestpath/pathfinder/WildernessChecker.java at 78593f7, FEROX_ENCLAVE_1 to 5: each {x, y, width,
	 * height}, on every floor). Not the semi-safe ground outside its barriers, nor the dungeon under it.
	 */
	static final int[][] FEROX = {{3123, 3622, 2, 10}, {3125, 3617, 16, 23}, {3138, 3636, 18, 10}, {3141, 3625, 14, 11},
		{3141, 3619, 7, 6}};

	static boolean inFerox(int x, int y)
	{
		for (int[] a : FEROX)
		{
			if (x >= a[0] && x < a[0] + a[2] && y >= a[1] && y < a[1] + a[3])
			{
				return true;
			}
		}
		return false;
	}

	/** In the Wilderness: within its bounds (an instance's template there too), or where the game's own
	 *  in-the-Wilderness flag says so (any part of it outside them); but never in Ferox Enclave, a haven (whatever the
	 *  flag says there, which couldn't be checked in the game). Kept apart from the client so it's tested. */
	static boolean wilderness(int x, int y, boolean insideFlag)
	{
		return !inFerox(x, y) && (inWilderness(x, y) || insideFlag);
	}

	/** In a PvP area: the game's PvP-area flag up, but not in Ferox Enclave and not in a PvP minigame's region
	 *  (11/10/2026, Jace: "there is no danger to someone tracking them there": Activity.PVP_MINIGAME_REGIONS). */
	static boolean pvpArea(int x, int y, int region, boolean pvpFlag)
	{
		return pvpFlag && !inFerox(x, y);
	}

	/**
	 * Safe for the globe's features (following and its world, the activity, the stars): not on a risky world (PvP,
	 * Deadman, high risk, Bounty Hunter), not in the Wilderness, not in a PvP area (each as above: Ferox Enclave and the
	 * PvP minigames are safe). Instances are (11/09/2026), unless their template lies in the Wilderness.
	 */
	static boolean globeSafe(boolean riskyWorld, boolean wilderness, boolean pvpArea)
	{
		return !riskyWorld && !wilderness && !pvpArea;
	}

	/**
	 * Safe for the activity's label (11/10/2026, Jace: "Wilderness bosses should be included since we have the option
	 * for 'In the Wilderness too'"): wherever the globe's features are, and in the Wilderness too (its PvP-area flag
	 * with it) when they've said so (OutsideConfig.wilderness), since they've already chosen to transmit there. Never
	 * on a risky world. Following and the stars stay off in the Wilderness whatever the setting (globeSafe): only the
	 * label goes, two minutes behind as ever.
	 */
	static boolean activitySafe(boolean riskyWorld, boolean wilderness, boolean pvpArea, boolean wildernessToo)
	{
		return globeSafe(riskyWorld, wilderness, pvpArea) || (wildernessToo && wilderness && !riskyWorld);
	}

	/**
	 * Where the stream holds (what they wear and carry, their vitals: Kit.held), unless "In the Wilderness too" is on:
	 * a PvP or Deadman world, the Wilderness, a PvP area. Not in Ferox Enclave or a PvP minigame (11/10/2026, Jace:
	 * "stream should keep going"), whatever the game's flags say there.
	 */
	static boolean held(boolean pvpWorld, boolean wilderness, boolean pvpArea)
	{
		return pvpWorld || wilderness || pvpArea;
	}

	/** On a world where nothing goes to the globe (RISKY, or any the client counts as PvP). */
	private boolean riskyWorld()
	{
		EnumSet<WorldType> types = client.getWorldType();
		if (pvpWorld())
		{
			return true;
		}
		for (WorldType t : types)
		{
			if (RISKY.contains(t))
			{
				return true;
			}
		}
		return false;
	}

	/** On a PvP or Deadman world (read here, never sent). */
	private boolean pvpWorld()
	{
		return WorldType.isPvpWorld(client.getWorldType()) || client.getWorldType().contains(WorldType.DEADMAN);
	}

	/** The Wilderness's bounds, above ground and below (its levels count from y 3520 up, and 9920 under). */
	static boolean inWilderness(int x, int y)
	{
		return x >= 2944 && x < 3392 && ((y >= 3520 && y < 3968) || (y >= 9920 && y < 10368));
	}

	static String accountType(int v)
	{
		switch (v)
		{
			case 1: return "IRONMAN";
			case 2: return "ULTIMATE_IRONMAN";
			case 3: return "HARDCORE_IRONMAN";
			case 4: return "GROUP_IRONMAN";
			case 5: return "HARDCORE_GROUP_IRONMAN";
			case 6: return "UNRANKED_GROUP_IRONMAN";
			default: return "NORMAL";
		}
	}

	private void say(String words)
	{
		if (panel != null)
		{
			panel.status(words);
		}
		clientThread.invokeLater(() -> chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Outside: " + words).build()));
	}
}

package wiki.outside;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Quests, achievement diaries, combat achievements and the slayer task (11/15/2026, Jace: "add quests, achievement
 * diaries, combat achievements and slayer tasks to the plugin"), read as the plugins that already read them do:
 * - quests: RuneLite's own Quest list and each one's state (the quest list plugin's way), and the quest points varp;
 * - diaries: each tier's completion varbit, Karamja's first three counting at 2 (0 not started, 1 started, 2 its tasks
 *   done) and the rest at 1, and each area's tasks done and in all from the game's own summary scripts, as Dink reads
 *   them (github.com/pajlads/DinkPlugin, DiaryNotifier and AchievementDiary: "Credits" in the README);
 * - combat achievements: the points varbit, each tier's tasks done and the points that tier needs;
 * - the slayer task: as RuneLite's own slayer plugin reads it, the creature's name from the game's slayer task table
 *   (a boss task's through the boss table), the area a master named from the area table, the amount given with the
 *   game's later changes to it, the points and the streak.
 * What reads the client runs on the client thread. The shapes are docs/protocol.md's ("quests", "diaries", "combat",
 * "slayer").
 */
final class Progress
{
	static final String[] AREAS = {"Ardougne", "Desert", "Falador", "Fremennik", "Kandarin", "Karamja", "Kourend & Kebos",
		"Lumbridge & Draynor", "Morytania", "Varrock", "Western Provinces", "Wilderness"};
	/** each area's id for the game's diary summary scripts, as Dink has them */
	static final int[] AREA_IDS = {1, 5, 2, 3, 4, 0, 11, 6, 7, 8, 10, 9};
	static final int[][] DIARY = {
		{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE},
		{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
	};
	/** the game's diary summary scripts: an area's tasks done, and in all (Dink's COMPLETED_AREA_TASKS_SCRIPT_ID, TOTAL_) */
	static final int AREA_DONE_SCRIPT = 4072, AREA_TOTAL_SCRIPT = 4073;

	static final String[] CA_TIERS = {"easy", "medium", "hard", "elite", "master", "grandmaster"};
	static final int[] CA_DONE = {VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY, VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM, VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD,
		VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE, VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER, VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER};
	static final int[] CA_NEEDS = {VarbitID.CA_THRESHOLD_EASY, VarbitID.CA_THRESHOLD_MEDIUM, VarbitID.CA_THRESHOLD_HARD,
		VarbitID.CA_THRESHOLD_ELITE, VarbitID.CA_THRESHOLD_MASTER, VarbitID.CA_THRESHOLD_GRANDMASTER};

	/** RuneLite's slayer plugin's tables and columns: the task table (its name), the boss table, the area table */
	static final int TASK_TABLE = 113, BOSS_TABLE = 116, AREA_TABLE = 115, BOSS_TASK = 98;
	static final int NAME_MAX = 80;

	private Progress()
	{
	}

	/** A tier done, from its varbit's value: Karamja's easy, medium and hard at 2, the rest at 1 (Dink's isComplete). */
	static boolean diaryDone(int varbit, int value)
	{
		if (varbit == VarbitID.ATJUN_EASY_DONE || varbit == VarbitID.ATJUN_MED_DONE || varbit == VarbitID.ATJUN_HARD_DONE)
		{
			return value > 1;
		}
		return value > 0;
	}

	/** One area: its four tiers (1 done, 0 not), then its tasks done and in all. */
	static JsonArray area(int[] varbits, int[] values, int done, int total)
	{
		JsonArray a = new JsonArray();
		for (int i = 0; i < 4; i++)
		{
			a.add(diaryDone(varbits[i], values[i]) ? 1 : 0);
		}
		a.add(Math.max(0, done));
		a.add(Math.max(0, total));
		return a;
	}

	/** Combat achievements: the points, then each tier's [tasks done, points it needs]. */
	static JsonObject combat(int points, int[] done, int[] needs)
	{
		JsonObject o = new JsonObject();
		o.addProperty("points", Math.max(0, points));
		JsonArray tiers = new JsonArray();
		for (int i = 0; i < CA_TIERS.length; i++)
		{
			JsonArray t = new JsonArray();
			t.add(Math.max(0, done[i]));
			t.add(Math.max(0, needs[i]));
			tiers.add(t);
		}
		o.add("tiers", tiers);
		return o;
	}

	/** Quests: the points, how many there are, and the names of those done, those started and the rest (the game's
	 *  quest list, green, yellow and red). */
	static JsonObject quests(int points, int total, List<String> done, List<String> started, List<String> todo)
	{
		JsonObject o = new JsonObject();
		o.addProperty("points", Math.max(0, points));
		o.addProperty("total", Math.max(0, total));
		o.add("done", names(done));
		o.add("started", names(started));
		o.add("todo", names(todo));
		return o;
	}

	/** One quest as the game's quest table has it (11/16/2026): its name, done (2), started (0) or not (1), free or members,
	 *  a miniquest or not, and its quest points. */
	static final class Q
	{
		final String name;
		final int state;
		final boolean members;
		final boolean mini;
		final int points;

		Q(String name, int state, boolean members, boolean mini, int points)
		{
			this.name = name;
			this.state = state;
			this.members = members;
			this.mini = mini;
			this.points = points;
		}
	}

	/**
	 * The quests as the game's own list groups them (11/16/2026, Jace: "it's nice being able to see which are free quests,
	 * which are members' quests, and which are mini-quests"): the names done, started and not, as before, and with them
	 * "free" (the free quests' names), "mini" (the miniquests') and "qp" (each quest's points, those with any), from which
	 * the page groups the list as the game does and writes the points in all. In the order given (the game's sort names).
	 */
	static JsonObject quests(int points, List<Q> list)
	{
		List<String> done = new java.util.ArrayList<>(), started = new java.util.ArrayList<>(), todo = new java.util.ArrayList<>();
		List<String> free = new java.util.ArrayList<>(), mini = new java.util.ArrayList<>();
		JsonObject qp = new JsonObject();
		for (Q q : list)
		{
			(q.state == 2 ? done : q.state == 1 ? todo : started).add(q.name);
			if (q.mini)
			{
				mini.add(q.name);
			}
			else if (!q.members)
			{
				free.add(q.name);
			}
			if (q.points > 0)
			{
				qp.addProperty(clip(q.name), q.points);
			}
		}
		JsonObject o = quests(points, list.size(), done, started, todo);
		o.add("free", names(free));
		o.add("mini", names(mini));
		o.add("qp", qp);
		return o;
	}

	/** The slayer task: null task when there's none (the points and streak still go). */
	static JsonObject slayer(String task, int left, int of, String area, int points, int streak)
	{
		JsonObject o = new JsonObject();
		boolean on = task != null && !task.isEmpty() && left > 0;
		o.add("task", on ? new com.google.gson.JsonPrimitive(clip(task)) : JsonNull.INSTANCE);
		o.addProperty("left", on ? left : 0);
		o.addProperty("of", on ? Math.max(left, of) : 0);
		o.add("area", on && area != null && !area.isEmpty() ? new com.google.gson.JsonPrimitive(clip(area)) : JsonNull.INSTANCE);
		o.addProperty("points", Math.max(0, points));
		o.addProperty("streak", Math.max(0, streak));
		return o;
	}

	/** The quests done in `now` and not in `before` (none when there's no before: the first read of a session). */
	static List<String> newlyDone(JsonObject before, JsonObject now)
	{
		List<String> out = new java.util.ArrayList<>();
		if (before == null || now == null)
		{
			return out;
		}
		java.util.Set<String> had = new java.util.HashSet<>();
		before.getAsJsonArray("done").forEach(e -> had.add(e.getAsString()));
		now.getAsJsonArray("done").forEach(e ->
		{
			if (!had.contains(e.getAsString()))
			{
				out.add(e.getAsString());
			}
		});
		return out;
	}

	/** A quest's points: its own, or (with none) its subquests' added up. */
	static int ownOrParts(int own, Integer parts)
	{
		return own > 0 ? own : parts == null ? 0 : Math.max(0, parts);
	}

	/** A field's first value, or null when the row has none. */
	private static Object field(Client c, int row, int column)
	{
		Object[] v = c.getDBTableField(row, column, 0);
		return v == null || v.length == 0 ? null : v[0];
	}

	private static int intOf(Object v, int otherwise)
	{
		return v instanceof Number ? ((Number) v).intValue() : otherwise;
	}

	private static boolean boolOf(Object v, boolean otherwise)
	{
		return v instanceof Boolean ? (Boolean) v : v instanceof Number ? ((Number) v).intValue() != 0 : otherwise;
	}

	private static JsonArray names(List<String> list)
	{
		JsonArray a = new JsonArray();
		for (String s : list)
		{
			a.add(clip(s));
		}
		return a;
	}

	private static String clip(String s)
	{
		String one = s.replaceAll("\\s+", " ").trim();
		return one.length() > NAME_MAX ? one.substring(0, NAME_MAX) : one;
	}

	// ---- read from the client (the client thread only) ----

	/** Everything the quest and diary reads depend on, cheaply: when it changes, they're read again. */
	static long signature(Client c)
	{
		long h = c.getVarpValue(VarPlayerID.QP);
		for (int[] tiers : DIARY)
		{
			for (int v : tiers)
			{
				h = h * 31 + c.getVarbitValue(v);
			}
		}
		return h;
	}

	/** The game's quest status script, as RuneLite's Quest.getState runs it: 2 done, 1 not started, else started. */
	static final int QUEST_STATUS = 4029;

	/**
	 * The quests from the game's own quest table (DBTableID.Quest), as its quest list shows them: every row but those it
	 * hides (its release type 0, not out yet) and the subquests (a parent quest: Recipe for Disaster's parts), each one's
	 * state by the game's status script; free or members, quest or miniquest (its type 1, the game's quest_is_miniquest)
	 * and quest points from the row. New quests come with the game, before RuneLite's Quest list has them. Sorted by the
	 * game's sort names ("Corsair Curse, The"). If the table can't be read, RuneLite's Quest list, ungrouped.
	 */
	static JsonObject readQuests(Client c)
	{
		try
		{
			List<Integer> rows = c.getDBTableRows(DBTableID.Quest.ID);
			if (rows != null && !rows.isEmpty())
			{
				List<Object[]> sorted = new java.util.ArrayList<>();
				// (a quest made of subquests has no points of its own: they're its subquests', which the list hides, so
				// they're added up for it; 11/16/2026, Jace's page said 342/339 for the game's 342/349: Recipe for Disaster's 10)
				java.util.Map<Integer, Integer> fromParts = new java.util.HashMap<>();
				for (int row : rows)
				{
					Object parent = field(c, row, DBTableID.Quest.COL_PARENT_QUEST);
					if (parent instanceof Number && !Integer.valueOf(0).equals(intOf(field(c, row, DBTableID.Quest.COL_RELEASE_TYPE), -1)))
					{
						fromParts.merge(((Number) parent).intValue(), Math.max(0, intOf(field(c, row, DBTableID.Quest.COL_QUESTPOINTS_OVERRIDE), 0)), Integer::sum);
					}
				}
				for (int row : rows)
				{
					if (Integer.valueOf(0).equals(intOf(field(c, row, DBTableID.Quest.COL_RELEASE_TYPE), -1)) || field(c, row, DBTableID.Quest.COL_PARENT_QUEST) != null)
					{
						continue;
					}
					Object name = field(c, row, DBTableID.Quest.COL_DISPLAYNAME), sort = field(c, row, DBTableID.Quest.COL_SORTNAME);
					if (!(name instanceof String) || ((String) name).isEmpty())
					{
						continue;
					}
					c.runScript(QUEST_STATUS, row);
					int st = c.getIntStack()[0];
					Q q = new Q((String) name, st == 2 ? 2 : st == 1 ? 1 : 0, boolOf(field(c, row, DBTableID.Quest.COL_MEMBERS), true),
						intOf(field(c, row, DBTableID.Quest.COL_TYPE), 0) == 1, ownOrParts(intOf(field(c, row, DBTableID.Quest.COL_QUESTPOINTS_OVERRIDE), 0), fromParts.get(row)));
					sorted.add(new Object[]{sort instanceof String ? sort : name, q});
				}
				sorted.sort((a, b) -> ((String) a[0]).compareToIgnoreCase((String) b[0]));
				List<Q> list = new java.util.ArrayList<>();
				for (Object[] e : sorted)
				{
					list.add((Q) e[1]);
				}
				if (!list.isEmpty())
				{
					return quests(c.getVarpValue(VarPlayerID.QP), list);
				}
			}
		}
		catch (RuntimeException e)
		{
			// (the table not as expected: RuneLite's own list below)
		}
		List<String> done = new java.util.ArrayList<>(), started = new java.util.ArrayList<>(), todo = new java.util.ArrayList<>();
		Quest[] all = Quest.values();
		for (Quest q : all)
		{
			QuestState s = q.getState(c);
			if (s == QuestState.FINISHED)
			{
				done.add(q.getName());
			}
			else if (s == QuestState.IN_PROGRESS)
			{
				started.add(q.getName());
			}
			else
			{
				todo.add(q.getName());
			}
		}
		return quests(c.getVarpValue(VarPlayerID.QP), all.length, done, started, todo);
	}

	static JsonObject readDiaries(Client c)
	{
		JsonObject o = new JsonObject();
		for (int i = 0; i < AREAS.length; i++)
		{
			int[] values = new int[4];
			for (int t = 0; t < 4; t++)
			{
				values[t] = c.getVarbitValue(DIARY[i][t]);
			}
			c.runScript(AREA_DONE_SCRIPT, AREA_IDS[i]);
			int done = c.getIntStack()[0];
			c.runScript(AREA_TOTAL_SCRIPT, AREA_IDS[i]);
			int total = c.getIntStack()[0];
			o.add(AREAS[i], area(DIARY[i], values, done, total));
		}
		return o;
	}

	static JsonObject readCombat(Client c)
	{
		int[] done = new int[CA_TIERS.length], needs = new int[CA_TIERS.length];
		for (int i = 0; i < CA_TIERS.length; i++)
		{
			done[i] = c.getVarbitValue(CA_DONE[i]);
			needs[i] = c.getVarbitValue(CA_NEEDS[i]);
		}
		return combat(c.getVarbitValue(VarbitID.CA_POINTS), done, needs);
	}

	/** What the slayer reads depend on, as a key: the names are looked up again only when it changes. */
	static String slayerKey(Client c)
	{
		return c.getVarpValue(VarPlayerID.SLAYER_COUNT) + ":" + c.getVarpValue(VarPlayerID.SLAYER_TARGET) + ":" + c.getVarpValue(VarPlayerID.SLAYER_AREA)
			+ ":" + c.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) + ":" + c.getVarpValue(4258) + ":" + c.getVarbitValue(15776) + ":" + c.getVarbitValue(15777)
			+ ":" + c.getVarbitValue(15778) + ":" + c.getVarbitValue(VarbitID.SLAYER_POINTS) + ":" + c.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
	}

	/** RuneLite's slayer plugin's updateTask, read the same way. */
	static JsonObject readSlayer(Client c)
	{
		int left = c.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int points = c.getVarbitValue(VarbitID.SLAYER_POINTS), streak = c.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		if (left <= 0)
		{
			return slayer(null, 0, 0, null, points, streak);
		}
		int target = c.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int row;
		if (target == BOSS_TASK)
		{
			List<Integer> boss = c.getDBRowsByValue(BOSS_TABLE, 1, 0, c.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (boss.isEmpty())
			{
				return slayer(null, 0, 0, null, points, streak);
			}
			row = (Integer) c.getDBTableField(boss.get(0), 4, 0)[0];
		}
		else
		{
			List<Integer> rows = c.getDBRowsByValue(TASK_TABLE, 0, 0, target);
			if (rows.isEmpty())
			{
				return slayer(null, 0, 0, null, points, streak);
			}
			row = rows.get(0);
		}
		String name = (String) c.getDBTableField(row, 10, 0)[0];
		String area = null;
		int areaId = c.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (areaId > 0)
		{
			List<Integer> a = c.getDBRowsByValue(AREA_TABLE, 0, 0, areaId);
			if (!a.isEmpty())
			{
				area = (String) c.getDBTableField(a.get(0), 3, 0)[0];
			}
		}
		// (the amount given, with the game's later changes to it: the slayer plugin's initialAmount)
		int of = c.getVarpValue(4258);
		if (c.getVarbitValue(15776) == 2)
		{
			int by = c.getVarbitValue(15777);
			of += c.getVarbitValue(15778) == 1 ? -by : by;
		}
		return slayer(name, left, of, area, points, streak);
	}
}

package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.security.SecureRandom;
import java.util.Base64;

/**
 * Tending the page's chat from the page (11/16/2026; docs/protocol.md, "Tending the page's chat from the page"): with the
 * plugin alone (the Plugin Hub's has no desk), "Tend my page's chat" makes a token, hands it to the relay with the page's
 * key (POST /tend/<channel>?key= {"token"}), and opens the page with it in the address's fragment, which no server sees.
 * There each visitor's line gets "take back" and "ban"; the token is good for 12 hours and can do nothing else. Kept apart
 * from RuneLite so it's tested.
 */
final class Tend
{
	private Tend()
	{
	}

	/** 32 random bytes as 43 base64url characters, no padding: what the relays take. */
	static String token(SecureRandom random)
	{
		byte[] b = new byte[32];
		random.nextBytes(b);
		return Base64.getUrlEncoder().withoutPadding().encodeToString(b);
	}

	/** The request's body: {"token": …}. */
	static String body(String token, Gson gson)
	{
		JsonObject o = new JsonObject();
		o.addProperty("token", token);
		return gson.toJson(o);
	}
}

